/* PACT — Partnership Intelligence. Workflow-first single-page application. */
(() => {
'use strict';
const SDG={1:['No poverty','#e5243b'],2:['Zero hunger','#dda63a'],3:['Good health','#4c9f38'],4:['Quality education','#c5192d'],5:['Gender equality','#ff3a21'],6:['Clean water','#26bde2'],7:['Clean energy','#fcc30b'],8:['Decent work','#a21942'],9:['Industry & innovation','#fd6925'],10:['Reduced inequalities','#dd1367'],11:['Sustainable cities','#fd9d24'],12:['Responsible consumption','#bf8b2e'],13:['Climate action','#3f7e44'],14:['Life below water','#0a97d9'],15:['Life on land','#56c02b'],16:['Peace & justice','#00689d'],17:['Partnerships','#19486a']};
const TYPES=['NGO','College','Startup','Company','Government','Community'];
const PAGES={overview:{title:'Command centre',group:'WORKSPACE',icon:'◈'},discover:{title:'Partner intelligence',group:'WORKSPACE',icon:'⌕'},market:{title:'Opportunity exchange',group:'WORKSPACE',icon:'⇄'},partnerships:{title:'Collaboration studio',group:'DELIVERY',icon:'▤'},impact:{title:'Impact observatory',group:'DELIVERY',icon:'◌'},network:{title:'Network map',group:'DELIVERY',icon:'⌘'},orgs:{title:'Organisation directory',group:'ECOSYSTEM',icon:'▦'},copilot:{title:'PACT copilot',group:'INTELLIGENCE',icon:'✳'},profile:{title:'Organisation workspace',group:'SETTINGS',icon:'⚙'},settings:{title:'AI & platform settings',group:'SETTINGS',icon:'☷'},admin:{title:'Trust & governance',group:'ADMIN',icon:'◆'}};
const $=(s,r=document)=>r.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=s=>{try{const u=new URL(String(s||''),location.origin);return ['http:','https:'].includes(u.protocol)?u.href:''}catch{return ''}};
const safeLink=s=>String(s||'').startsWith('#')?esc(s):esc(safeUrl(s)||'#/');
const S={token:localStorage.getItem('pact_token')||localStorage.getItem('ph_token'),user:null,unread:0,chat:[],curPart:null,ws:null,routeSeq:0};
const initials=s=>String(s||'?').trim().split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase();
const sdgChips=ids=>(ids||[]).map(n=>`<span class="sdg-chip" style="background:${SDG[n]?.[1]||'#68768a'}" title="SDG ${n}: ${esc(SDG[n]?.[0])}">${n}</span>`).join('');
const orgAvatar=(o,idx=0)=>`<span class="org-avatar ${['','teal','orange','purple','rose'][idx%5]}">${esc(initials(o?.name))}</span>`;
const pill=(s)=>`<span class="pill ${({'active':'green','completed':'blue','proposed':'orange','negotiating':'blue','declined':'red','verified':'green','need':'orange','offer':'green'}[String(s).toLowerCase()]||'')}">${esc(s)}</span>`;
const num=n=>Number(n||0).toLocaleString('en-IN');
function toast(message,error=false){const t=document.createElement('div');t.className='toast'+(error?' error':'');t.textContent=message;$('#toasts').append(t);setTimeout(()=>t.remove(),4500)}
async function api(path,opts={}){const headers={...(S.token?{Authorization:'Bearer '+S.token}:{})};let body=opts.body;if(body!==undefined){headers['Content-Type']='application/json';body=JSON.stringify(body)}let r;try{r=await fetch('/api'+path,{method:opts.method||'GET',headers,body})}catch{throw new Error('The server is unreachable. Check that PACT is running.')}if(r.status===401&&S.token&&!path.startsWith('/auth/login')){logout();throw new Error('Your session expired. Please sign in again.')}if(opts.raw&&r.ok)return r;const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(Array.isArray(d.detail)?d.detail.map(x=>x.msg).join(', '):d.detail||'Request failed.');return d}
async function act(button,fn){if(button)button.disabled=true;try{return await fn()}catch(e){toast(e.message,true)}finally{if(button)button.disabled=false}}
function logout(){localStorage.removeItem('pact_token');localStorage.removeItem('ph_token');S.token=S.user=null;S.ws?.close();location.hash='';authView()}
function logo(){return `<div class="brand-mark">P</div>`}
function authView(mode='login'){$('#app').innerHTML=`<div class="auth-layout"><section class="auth-story"><div class="brand-lockup">${logo()}<div><strong>PACT</strong><small>Partnership intelligence</small></div></div><div class="auth-copy"><span class="eyebrow">● SDG 17 · Partnerships for the goals</span><h1>Good intentions need a <span style="color:var(--accent)">system.</span></h1><p>Turn fragmented offers, unmet needs and promising introductions into coordinated work with measurable outcomes.</p><div class="auth-points"><div class="auth-point"><b>01 / Discover</b>Find partners by fit, not just keywords.</div><div class="auth-point"><b>02 / Coordinate</b>Move from introduction to milestones.</div><div class="auth-point"><b>03 / Prove</b>Track outcomes with context and evidence.</div><div class="auth-point"><b>04 / Learn</b>Use AI to plan the next best action.</div></div></div><div class="auth-foot">A collaboration operating system · Built around SDG 17</div></section><section class="auth-panel"><form class="auth-form" id="auth-form"><span class="eyebrow">${mode==='login'?'WELCOME BACK':'GET STARTED'}</span><h2>${mode==='login'?'Sign in to PACT':'Build your organisation space'}</h2><p>${mode==='login'?'Pick up where your partnerships left off.':'Join a network built to turn shared resources into action.'}</p>${mode==='register'?`<div class="form-grid"><div class="field"><label>Your full name</label><input name="full_name" required minlength="2" autocomplete="name"></div><div class="field"><label>Organisation name</label><input name="org_name" required minlength="2"></div></div><div class="form-grid"><div class="field"><label>Organisation type</label><select name="org_type">${TYPES.map(t=>`<option>${t}</option>`).join('')}</select></div><div class="field"><label>Sector</label><input name="sector" placeholder="e.g. clean energy"></div></div><div class="form-grid"><div class="field"><label>City</label><input name="city" placeholder="City"></div><div class="field"><label>Country</label><input name="country" value="India"></div></div>`:''}<div class="field"><label>Email address</label><input name="email" type="email" required autocomplete="username" placeholder="you@organisation.org"></div><div class="field"><label>Password</label><input name="password" type="password" minlength="8" required autocomplete="${mode==='login'?'current-password':'new-password'}" placeholder="${mode==='login'?'Enter your password':'At least 8 characters'}"></div><button class="btn primary" style="width:100%;margin-top:5px" type="submit">${mode==='login'?'Continue to workspace →':'Create organisation workspace →'}</button><div class="auth-switch">${mode==='login'?'New to PACT?':'Already have an account?'} <button type="button" class="text-btn" id="switch-auth">${mode==='login'?'Create an account':'Sign in instead'}</button></div>${mode==='login'?`<div class="demo-hint"><b>Demo environment</b><br>Use the demo account configured in your README or local database. Avoid using demo credentials on a public deployment.</div>`:''}</form></section></div>`;
$('#switch-auth').onclick=()=>authView(mode==='login'?'register':'login');$('#auth-form').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.currentTarget));await act(e.submitter,async()=>{const r=await api('/auth/'+(mode==='login'?'login':'register'),{method:'POST',body:b});S.token=r.token;localStorage.setItem('pact_token',r.token);localStorage.removeItem('ph_token');await boot()})}}
function applyTheme(theme){
  const chosen = theme === 'dark' ? 'dark' : 'light';
  document.documentElement.dataset.theme = chosen;
  localStorage.setItem('pact_theme', chosen);
  const btn = document.getElementById('theme-toggle');
  if (btn) {
    btn.textContent = chosen === 'dark' ? '☼' : '◐';
    btn.setAttribute('aria-label', chosen === 'dark' ? 'Switch to light theme' : 'Switch to dark theme');
    btn.title = chosen === 'dark' ? 'Switch to light theme' : 'Switch to dark theme';
  }
}
function initTheme(){
  const saved = localStorage.getItem('pact_theme');
  const systemDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
  applyTheme(saved || (systemDark ? 'dark' : 'light'));
}
initTheme();
function shell(){const u=S.user;const groups=['WORKSPACE','DELIVERY','ECOSYSTEM','INTELLIGENCE','SETTINGS'];const items=groups.map(g=>{const links=Object.entries(PAGES).filter(([k,v])=>v.group===g&&!(k==='admin'&&u.role!=='admin'));return links.length?`<div class="workspace-label">${g}</div><div class="nav-list">${links.map(([k,p])=>`<a href="#/${k==='overview'?'':k}" class="nav-link" data-nav="${k}"><span class="nav-icon">${p.icon}</span><span>${p.title}</span>${k==='partnerships'?`<span class="nav-count" id="nav-pcount">·</span>`:''}</a>`).join('')}</div>`:''}).join('');$('#app').innerHTML=`<div class="app-frame"><aside class="sidebar" id="sidebar"><div class="sidebar-brand">${logo()}<div><strong>PACT</strong><small>Partnership intelligence</small></div></div>${items}<div class="sidebar-spacer"></div><div class="sdg-mini"><div class="mini-top"><span class="sdg17">17</span><span>Partnerships for the goals</span></div><p>Progress happens when resources, expertise and accountability meet.</p><div class="mini-progress"><i></i></div></div><div class="profile-chip"><div class="avatar">${esc(initials(u.full_name))}</div><div style="min-width:0;flex:1"><strong>${esc(u.full_name)}</strong><small>${esc(u.org?.name||'Platform administrator')}</small></div><button class="signout" id="signout" title="Sign out" aria-label="Sign out">↗</button></div></aside><section class="main-area"><header class="topbar"><button class="icon-btn mobile-menu" id="mobile-menu" aria-label="Open navigation">☰</button><div class="breadcrumbs">PACT <span style="padding:0 7px;color:#bdc6d3">/</span><b id="crumb">Command centre</b></div><div class="top-search"><span>⌕</span><input id="global-search" placeholder="Search organisations, needs, offers…" aria-label="Search platform"></div><button class="icon-btn theme-toggle" id="theme-toggle" aria-label="Switch theme" title="Switch light/dark theme">◐</button><button class="icon-btn" id="notif-btn" aria-label="Notifications">♧<span class="notif-dot ${S.unread?'':'hidden'}" id="notif-dot"></span></button><div class="avatar" title="${esc(u.org?.name||u.full_name)}">${esc(initials(u.org?.name||u.full_name))}</div><div class="notification-panel hidden" id="notif-panel"></div></header><main class="content" id="view"><div class="skeleton"></div></main></section></div>`;$('#signout').onclick=logout;$('#theme-toggle').onclick=()=>applyTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');applyTheme(localStorage.getItem('pact_theme')||document.documentElement.dataset.theme||'light');$('#mobile-menu').onclick=()=>$('#sidebar').classList.toggle('open');$('#notif-btn').onclick=async()=>{const p=$('#notif-panel');p.classList.toggle('hidden');if(!p.classList.contains('hidden'))await loadNotifications()};$('#global-search').onkeydown=e=>{if(e.key==='Enter'){const q=e.target.value.trim();location.hash='#/market?q='+encodeURIComponent(q)}}}
async function loadNotifications(){const p=$('#notif-panel');try{const ns=await api('/notifications');p.innerHTML=`<div class="card-head" style="padding:13px 13px 0"><h3>Notifications</h3><button class="btn small secondary" id="mark-read">Mark read</button></div>`+(ns.length?ns.map(n=>`<a class="notification-item ${n.read?'':'unread'}" href="${safeLink(n.link||'#/')}" data-nlink>${esc(n.text)}<small>${esc(n.created_at||'')}</small></a>`).join(''):`<div class="empty-state"><div class="empty-icon">♧</div><h3>All caught up</h3><p>No notifications yet.</p></div>`);$('#mark-read').onclick=async()=>{await api('/notifications/read',{method:'POST'});S.unread=0;$('#notif-dot').classList.add('hidden');toast('Notifications marked as read')};p.querySelectorAll('[data-nlink]').forEach(a=>a.addEventListener('click',()=>p.classList.add('hidden')))}catch(e){p.innerHTML=`<div class="notification-item">${esc(e.message)}</div>`}}
const pageHead=(eyebrow,title,sub,actions='')=>`<div class="page-head"><div><div class="kicker">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(sub||'')}</p></div><div class="page-actions">${actions}</div></div>`;
const cardHead=(title,extra='')=>`<div class="card-head"><h2>${title}</h2>${extra}</div>`;
const stat=(label,value,foot,icon,trend='')=>`<article class="card stat-card"><div class="stat-top"><span>${esc(label)}</span><span class="stat-icon">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${trend?`<span class="trend">${trend}</span> · `:''}${foot}</div></article>`;
const empty=(title,copy,cta='')=>`<div class="empty-state"><div class="empty-icon">✳</div><h3>${esc(title)}</h3><p>${esc(copy)}</p>${cta}</div>`;
const barChart=weeks=>{const max=Math.max(1,...weeks.map(x=>x.count));return `<div class="bar-chart">${weeks.map(w=>`<div class="bar-item"><b>${w.count||''}</b><div class="bar" style="height:${Math.max(3,100*w.count/max)}%" title="${w.count} partnerships"></div><small>${esc(w.label)}</small></div>`).join('')}</div>`};
async function route(){if(!S.user)return;const raw=location.hash.replace(/^#\/?/,'');const [keyAndQuery,id]=raw.split('/');const [page='overview',query='']=keyAndQuery.split('?');let routeKey=page||'overview';if(!S.user.org&&S.user.role==='admin'&&routeKey==='overview')routeKey='admin';const seq=++S.routeSeq;const target=$('#view');if(!target)return;$('#sidebar').classList.remove('open');document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',(a.dataset.nav==='overview'&&routeKey==='overview')||a.dataset.nav===routeKey||(routeKey==='partnership'&&a.dataset.nav==='partnerships')||(routeKey==='org'&&a.dataset.nav==='orgs')));$('#crumb').textContent=PAGES[routeKey]?.title||({'partnership':'Collaboration workspace','org':'Organisation profile'}[routeKey]||'PACT workspace');target.innerHTML='<div class="skeleton"></div><div class="skeleton" style="margin-top:16px"></div>';try{if(routeKey==='partnership')await partnershipPage(target,id);else if(routeKey==='org')await orgPage(target,id);else if(routeKey==='overview')await dashboardPage(target);else if(routeKey==='discover')await discoverPage(target);else if(routeKey==='market')await marketPage(target,query);else if(routeKey==='partnerships')await partnershipsPage(target);else if(routeKey==='impact')await impactPage(target);else if(routeKey==='network')await networkPage(target);else if(routeKey==='orgs')await directoryPage(target);else if(routeKey==='copilot')await copilotPage(target);else if(routeKey==='profile')await profilePage(target);else if(routeKey==='settings')await settingsPage(target);else if(routeKey==='admin')await adminPage(target);else await dashboardPage(target);if(seq!==S.routeSeq)return}catch(e){if(seq!==S.routeSeq)return;target.innerHTML=`<div class="error-card"><h2>We couldn't load this workspace</h2><p class="muted">${esc(e.message)}</p><button class="btn primary" id="retry">Try again</button></div>`;$('#retry').onclick=route}}
window.addEventListener('hashchange',route);
async function dashboardPage(v){const [ov,ms,imp,ps]=await Promise.all([api('/analytics/overview'),api('/matches'),api('/analytics/impact'),api('/partnerships')]);const open=ps.filter(p=>['proposed','negotiating','active'].includes(p.status));const best=ms.slice(0,3);const gaps=ov.gaps||[];v.innerHTML=pageHead('YOUR ECOSYSTEM / LIVE VIEW',`Good ${new Date().getHours()<12?'morning':new Date().getHours()<18?'afternoon':'evening'}, ${S.user.full_name.split(' ')[0]}.`,'Your partnership operations, surfaced as the next best actions.',`<a class="btn secondary" href="#/impact">View impact ↗</a><a class="btn lime" href="#/profile">+ Publish opportunity</a>`)+`<div class="layout-grid cols-4">${stat('Active collaborations',imp.active,`${imp.completed} completed`,'⇄')}${stat('Potential partners',ms.length,ms[0]?`Top fit ${Math.round(ms[0].score)}/100`:'Publish a need to improve matches','⌕')}${stat('Milestones completed',`${imp.milestones_done}/${imp.milestones_total}`,`${imp.milestones_total?Math.round(100*imp.milestones_done/imp.milestones_total):0}% delivery progress`,'✓')}${stat('Organisation trust',`${imp.trust}<span style="font-size:13px;color:var(--muted)">/100</span>`,S.user.org?.verified?'Verification active':'Verification pending','◇')}</div><div class="split section-gap"><section class="card">${cardHead('Recommended next connections',`<a class="btn small secondary" href="#/discover">View all matches →</a>`)}<div class="list-stack">${best.map((m,i)=>`<div class="list-row">${orgAvatar(m.org,i)}<div class="grow"><strong>${esc(m.org.name)} ${m.org.verified?'<span class="pill green">✓ verified</span>':''}</strong><p>${esc(m.org.type)} · ${esc(m.org.sector||'Cross-sector partner')} · ${m.they_give?.[0]?`Can help with ${esc(m.they_give[0].need)}`:'Potential strategic fit'}</p><div class="match-meter"><i style="width:${Math.min(100,m.score)}%"></i></div></div><div style="text-align:right"><div class="match-score">${Math.round(m.score)}</div><small class="muted tiny">FIT SCORE</small><div><a class="btn small soft" href="#/org/${m.org_id}">Explore</a></div></div></div>`).join('')||empty('No matches yet','Publish an open need or offer so PACT can discover complementary organisations.','<a class="btn primary" href="#/profile">Create first opportunity</a>')}</div></section><section class="card">${cardHead('Your action queue','<span class="pill orange">LIVE</span>')}<div class="list-stack">${open.slice(0,4).map(p=>`<a class="list-row" href="#/partnership/${p.id}"><span class="stat-icon">${p.status==='proposed'?'✉':'⇄'}</span><div class="grow"><strong>${esc(p.title)}</strong><p>${esc(p.other.name)} · ${esc(p.status)}</p></div><span>→</span></a>`).join('')||empty('Nothing waiting','Your open proposals and active collaborations will appear here.')}<a class="list-row" href="#/market"><span class="stat-icon">⌕</span><div class="grow"><strong>Explore the opportunity exchange</strong><p>${ov.open_needs} needs and ${ov.open_offers} offers currently open</p></div><span>→</span></a></div></section></div><div class="layout-grid cols-2 section-gap"><section class="card">${cardHead('Collaboration momentum','<span class="pill blue">LAST 8 WEEKS</span>')}${barChart(ov.weekly||[])}<div class="divider"></div><div class="layout-grid cols-3"><div><div class="stat-value" style="font-size:22px">${ov.orgs}</div><div class="muted tiny">Organisations</div></div><div><div class="stat-value" style="font-size:22px">${ov.open_needs}</div><div class="muted tiny">Open needs</div></div><div><div class="stat-value" style="font-size:22px">${ov.open_offers}</div><div class="muted tiny">Open offers</div></div></div></section><section class="card">${cardHead('Unmet ecosystem needs','<a href="#/market" class="btn small secondary">Explore exchange</a>')}<div class="list-stack">${gaps.slice(0,4).map(g=>`<div class="list-row"><span class="stat-icon" style="background:var(--orange-soft);color:var(--orange)">!</span><div class="grow"><strong>${esc(g.title)}</strong><p>${esc(g.org)} · ${g.best_similar?`Closest related offer: ${esc(g.best_similar)}`:'No close offer found yet'}</p></div></div>`).join('')||empty('No gaps detected','As new needs and offers are added, PACT will surface gaps in the network.')}</div></section></div><p class="footer-note">PACT recommendations are decision support, not guarantees. Verify partner claims and agree on evidence before reporting outcomes.</p>`;}
async function discoverPage(v){const ms=await api('/matches');window._pactMatches=Object.fromEntries(ms.map(m=>[m.org_id,m]));v.innerHTML=pageHead('INTELLIGENCE / MATCHMAKING','Find the right partner, with reasons.','PACT ranks complementary needs and offers, then shows the signals behind each score.',`<a class="btn secondary" href="#/market">Browse all opportunities →</a>`)+(ms.length?`<div class="layout-grid cols-2">${ms.map((m,i)=>`<article class="card"><div class="row" style="display:flex;align-items:flex-start;gap:12px">${orgAvatar(m.org,i)}<div style="flex:1;min-width:0"><h2 style="margin:0 0 3px">${esc(m.org.name)}</h2><p class="muted small-text" style="margin:0">${esc(m.org.type)} · ${esc(m.org.sector||'Cross-sector')}</p><div class="tag-row">${m.org.verified?'<span class="pill green">✓ Verified</span>':''}${sdgChips(m.shared_sdgs)}</div></div><div style="text-align:right"><div class="match-score" style="font-size:29px">${Math.round(m.score)}</div><span class="muted tiny">FIT / 100</span></div></div><div class="match-meter" style="margin:15px 0 18px"><i style="width:${m.score}%"></i></div><div class="layout-grid cols-2"><div><div class="kicker">They can contribute</div>${(m.they_give||[]).slice(0,3).map(x=>`<div class="metric-row"><span class="stat-icon" style="background:var(--teal-soft);color:var(--teal)">＋</span><div><strong class="small-text">${esc(x.offer)}</strong><div class="muted tiny">Matches: ${esc(x.need)}</div></div></div>`).join('')||'<p class="muted tiny">No direct need/offer pair yet.</p>'}</div><div><div class="kicker">You could contribute</div>${(m.you_give||[]).slice(0,3).map(x=>`<div class="metric-row"><span class="stat-icon">↗</span><div><strong class="small-text">${esc(x.offer)}</strong><div class="muted tiny">For their need: ${esc(x.need)}</div></div></div>`).join('')||'<p class="muted tiny">Add offers to reveal two-way opportunities.</p>'}</div></div><div class="divider"></div><div class="layout-grid cols-2">${Object.entries(m.breakdown||{}).map(([k,val])=>`<div><div class="row" style="justify-content:space-between;font-size:10px"><span class="muted">${esc(({semantic:'Meaning similarity',sdg:'Shared SDGs',geo:'Geography',trust:'Trust signals',reciprocity:'Reciprocity'}[k]||k))}</span><b>${val}%</b></div><div class="match-meter"><i style="width:${val}%;background:${k==='trust'?'var(--teal)':'var(--blue)'}"></i></div></div>`).join('')}</div><div class="row" style="margin-top:18px"><button class="btn secondary small" data-explain="${m.org_id}">✳ Explain match</button><button class="btn secondary small" data-outreach="${m.org_id}">Draft introduction</button><span style="flex:1"></span><a class="btn secondary small" href="#/org/${m.org_id}">Profile</a>${m.existing?'':`<button class="btn primary small" data-start="${m.org_id}">Propose partnership →</button>`}</div></article>`).join('')}</div>`:empty('Your matching engine is ready','Create at least one need and one offer in your organisation workspace. PACT will use them to identify complementary partners.','<a class="btn primary" href="#/profile">Set up organisation</a>'))}
function showProposal(orgId,plan,score){const m=$('#modal');m.className='modal';m.innerHTML=`<h2 id="modal-title">Draft a collaboration</h2><p class="muted small-text">AI suggestions are editable. Confirm scope and commitments with the partner before sending.</p><form id="proposal-form"><div class="field"><label>Collaboration title</label><input name="title" required minlength="3" value="${esc(plan.title||'Cross-sector SDG 17 collaboration')}"></div><div class="field"><label>Shared objective</label><textarea name="summary">${esc(plan.summary||'Work together on a measurable SDG-aligned outcome.')}</textarea></div><div class="field"><label>Proposed milestones (one per line)</label><textarea name="milestones">${esc((plan.milestones||['Confirm scope and success measures','Assign owners and timeline','Deliver pilot activity','Review evidence and publish outcomes']).join('\n'))}</textarea></div><div class="modal-footer"><button type="button" class="btn secondary" data-close>Cancel</button><button class="btn primary">Send proposal →</button></div></form>`;m.showModal();$('#proposal-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);await act(e.submitter,async()=>{const r=await api('/partnerships',{method:'POST',body:{org_id:+orgId,title:f.get('title'),summary:f.get('summary'),match_score:score,milestones:f.get('milestones').split('\n').filter(Boolean)}});m.close();toast('Proposal sent');location.hash='#/partnership/'+r.id})}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-explain],[data-outreach],[data-start],[data-close]');if(!b)return;if(b.hasAttribute('data-close')){$('#modal').close();return}const id=+(b.dataset.explain||b.dataset.outreach||b.dataset.start);await act(b,async()=>{if(b.hasAttribute('data-explain')){const r=await api('/ai/explain',{method:'POST',body:{org_id:id}});const m=$('#modal');m.className='modal';m.innerHTML=`<h2 id="modal-title">Why this match?</h2><p class="muted tiny">${r.ai?'AI-generated explanation':'Built-in explainable matching summary'}</p><div style="white-space:pre-wrap;line-height:1.8">${esc(r.text)}</div><div class="modal-footer"><button class="btn secondary" data-close>Close</button><button class="btn primary" data-start="${id}">Build proposal →</button></div>`;m.showModal()}else if(b.hasAttribute('data-outreach')){const r=await api('/ai/outreach',{method:'POST',body:{org_id:id}});const m=$('#modal');m.className='modal';m.innerHTML=`<h2 id="modal-title">Introduction draft</h2><p class="muted tiny">Review and personalise before sending.</p><textarea id="outreach-copy" style="width:100%;min-height:220px;border:1px solid var(--line);border-radius:12px;padding:13px">${esc(r.text)}</textarea><div class="modal-footer"><button class="btn secondary" data-close>Close</button><button class="btn primary" id="copy-outreach">Copy draft</button></div>`;m.showModal();$('#copy-outreach').onclick=async()=>{try{await navigator.clipboard.writeText($('#outreach-copy').value);toast('Draft copied')}catch{toast('Select and copy the draft manually',true)}}}else{const r=await api('/ai/plan',{method:'POST',body:{org_id:id}});showProposal(id,r,window._pactMatches?.[id]?.score||0)}})});
async function marketPage(v,query=''){let q=new URLSearchParams(query).get('q')||'';v.innerHTML=pageHead('ECOSYSTEM / OPEN EXCHANGE','Turn resources into opportunities.','Browse open needs and offers across the SDG network. Search is meaning-aware, not just keyword-based.',`<a class="btn lime" href="#/profile">+ Publish an opportunity</a>`)+`<div class="filterbar"><input id="market-q" value="${esc(q)}" placeholder="Try: solar installation, volunteer data analysts, clean water sensors…"><select id="market-kind"><option value="">Needs + offers</option><option value="need">Needs only</option><option value="offer">Offers only</option></select><select id="market-sdg"><option value="0">All SDGs</option>${Object.entries(SDG).map(([n,d])=>`<option value="${n}">${n} · ${esc(d[0])}</option>`).join('')}</select><button class="btn secondary" id="clear-market">Reset</button></div><div class="row" style="justify-content:space-between;margin-bottom:12px"><span id="market-count" class="muted tiny">Loading opportunities…</span><span class="pill green">OPEN OPPORTUNITIES</span></div><div class="market-grid" id="market-results"></div>`;const load=async()=>{const params=new URLSearchParams({q:$('#market-q').value,kind:$('#market-kind').value,sdg_id:$('#market-sdg').value});const rows=await api('/listings?'+params);$('#market-count').textContent=`${rows.length} opportunities found`;$('#market-results').innerHTML=rows.length?rows.map((l,i)=>`<article class="card opportunity-card"><div class="op-kind">${pill(l.kind)}<span class="muted tiny">${l.relevance!=null?`${l.relevance}% relevance`:l.remote_ok?'Remote-friendly':'Location-based'}</span></div><h3>${esc(l.title)}</h3><p class="description">${esc(l.description||'No description provided.')}</p><div class="tag-row">${sdgChips(l.sdgs)}</div><div class="op-bottom"><div class="row" style="gap:8px">${orgAvatar({name:l.org},i)}<div><strong class="small-text">${esc(l.org)}</strong><div class="muted tiny">${l.org_verified?'✓ Verified organisation':'Community organisation'}</div></div></div><a class="btn secondary small" href="#/org/${l.org_id}">View →</a></div></article>`).join(''):empty('No opportunities match yet','Try a broader search or remove one of the filters.','<button class="btn secondary" id="empty-reset">Clear filters</button>');$('#empty-reset')?.addEventListener('click',()=>{$('#market-q').value='';$('#market-kind').value='';$('#market-sdg').value='0';load()})};let timer;$('#market-q').oninput=()=>{clearTimeout(timer);timer=setTimeout(()=>load().catch(e=>toast(e.message,true)),280)};$('#market-kind').onchange=load;$('#market-sdg').onchange=load;$('#clear-market').onclick=()=>{$('#market-q').value='';$('#market-kind').value='';$('#market-sdg').value='0';load()};await load()}
async function partnershipsPage(v){const ps=await api('/partnerships');const states=['proposed','negotiating','active','completed','declined'];v.innerHTML=pageHead('DELIVERY / COLLABORATION PIPELINE','Move commitments into action.','Every partnership has an owner, a stage, milestones and a record of outcomes.',`<a class="btn lime" href="#/discover">Find a partner →</a>`)+`<div class="layout-grid cols-4" style="margin-bottom:18px">${states.slice(0,4).map(s=>stat(s[0].toUpperCase()+s.slice(1),ps.filter(p=>p.status===s).length,s==='proposed'?'Waiting for response':s==='active'?'In delivery':s==='completed'?'Outcome recorded':'In discussion',({'proposed':'✉','negotiating':'↔','active':'▶','completed':'✓'}[s]))) .join('')}</div><div class="kanban">${states.map(s=>`<section class="kanban-col"><div class="kanban-title">${esc(s)} <span>${ps.filter(p=>p.status===s).length}</span></div>${ps.filter(p=>p.status===s).map(p=>`<a class="kanban-card" href="#/partnership/${p.id}"><strong>${esc(p.title)}</strong><small>${esc(p.other.name)}</small><div class="progress-track" style="margin-top:12px"><i style="width:${p.progress}%"></i></div><small>${p.progress}% milestones complete · updated ${esc((p.updated_at||'').slice(0,10))}</small></a>`).join('')||`<div class="muted tiny" style="padding:14px 6px">No collaborations here.</div>`}</section>`).join('')}</div>`}
async function partnershipPage(v,id){S.curPart=+id;const p=await api('/partnerships/'+id);const flow={proposed:p.you_initiated?[['declined','Withdraw proposal','danger']]:[['negotiating','Accept & negotiate','primary'],['declined','Decline','danger']],negotiating:[['active','Start delivery','primary'],['declined','Close proposal','danger']],active:[['completed','Mark completed','primary']],completed:[],declined:[]}[p.status]||[];v.innerHTML=pageHead('DELIVERY / COLLABORATION WORKSPACE',p.title,`${p.me.name} × ${p.other.name}`,`<a class="btn secondary" href="#/partnerships">← Pipeline</a>${flow.map(([s,t,c])=>`<button class="btn ${c}" data-status="${s}">${t}</button>`).join('')}`)+`<div class="card" style="margin-bottom:18px"><div class="row" style="justify-content:space-between;gap:18px"><div><div class="tag-row">${pill(p.status)}<span class="pill blue">${Math.round(p.match_score)} fit score</span></div><p style="margin:12px 0 0;max-width:820px">${esc(p.summary||'No shared objective recorded yet.')}</p></div><div style="min-width:130px;text-align:right"><div class="stat-value" style="font-size:27px">${p.progress}%</div><div class="muted tiny">DELIVERY PROGRESS</div><div class="progress-track" style="margin-top:8px"><i style="width:${p.progress}%"></i></div></div></div></div><div class="workspace-two"><div class="layout-grid"><section class="card">${cardHead('Milestone plan',`<span class="pill">${p.milestones.filter(m=>m.done).length}/${p.milestones.length} done</span>`)}<div id="milestones">${p.milestones.map(m=>`<label class="milestone ${m.done?'done':''}"><input type="checkbox" data-milestone="${m.id}" ${m.done?'checked':''}><span style="flex:1"><span class="milestone-name">${esc(m.title)}</span><small>${m.due?`Due ${esc(m.due)}`:'No due date set'}</small></span>${m.done?'<span class="pill green">Done</span>':''}</label>`).join('')||empty('No milestones yet','Break the collaboration into small, owned deliverables.')}</div><form id="add-milestone" class="form-inline"><input name="title" placeholder="Add a milestone…" required minlength="2"><input name="due" type="date" style="max-width:145px"><button class="btn primary">Add</button></form></section><section class="card">${cardHead('Impact ledger','<span class="pill green">SDG-ALIGNED</span>')}<div>${p.metrics.map(m=>`<div class="metric-row">${sdgChips([m.sdg])}<div style="flex:1"><strong class="small-text">${esc(m.name)}</strong><div class="muted tiny">${esc(m.unit||'unit not set')} · ${esc(m.verification_status||'self_reported')}</div>${m.evidence_url?`<a class="muted tiny" href="${safeUrl(m.evidence_url)}" target="_blank" rel="noopener noreferrer">View evidence ↗</a>`:''}</div><div class="metric-number">${num(m.value)}</div></div>`).join('')||empty('No outcomes recorded','Add metrics that describe what changed—not just what activities happened.')}</div><form id="add-metric" class="section-gap"><div class="field"><label>Impact metric</label><input name="name" placeholder="e.g. Students trained" required minlength="2"></div><div class="form-grid"><div class="field"><label>SDG</label><select name="sdg">${Object.entries(SDG).map(([n,d])=>`<option value="${n}">${n} · ${esc(d[0])}</option>`).join('')}</select></div><div class="field"><label>Value</label><input name="value" type="number" step="any" required placeholder="0"></div></div><div class="field"><label>Unit</label><input name="unit" placeholder="people, kg, INR…"></div><div class="field"><label>Evidence URL (optional)</label><input name="evidence_url" type="url" placeholder="https://…"><small class="muted tiny">Add a public report or source link. A URL does not automatically verify the claim.</small></div><button class="btn secondary" style="width:100%">+ Record outcome</button></form><p class="footer-note">Only metrics reviewed by an administrator are marked verified; review does not guarantee that the source itself is authentic.</p></section></div><aside class="layout-grid"><section class="card">${cardHead('Partner context',`<a class="btn small secondary" href="#/org/${p.other.id}">View profile</a>`)}<div class="row">${orgAvatar(p.other)}<div><strong>${esc(p.other.name)}</strong><div class="muted tiny">${esc(p.other.type)} · ${esc(p.other.city||'')}</div></div></div><div class="tag-row">${sdgChips(p.other.sdgs)}${p.other.verified?'<span class="pill green">✓ Verified</span>':''}</div><div class="divider"></div><div class="row" style="justify-content:space-between"><span class="muted small-text">Partner trust score</span><b>${p.other.trust??'—'}/100</b></div></section><section class="card">${cardHead('Partner conversation','<span class="pill">SHARED</span>')}<div class="chat-box" id="part-chat">${p.messages.map(m=>`<div class="chat-msg ${m.org_id===p.me.id?'mine':''}"><small>${esc(m.user)} · ${esc((m.created_at||'').replace('T',' ').slice(0,16))}</small>${esc(m.body)}</div>`).join('')||'<div class="muted tiny">Start the conversation with a clear next step.</div>'}</div><form id="send-message" class="form-inline"><input name="body" placeholder="Write a message…" required maxlength="4000"><button class="btn primary">Send</button></form></section>${p.status==='completed'?`<section class="card">${cardHead('Partner review')} ${p.reviews.map(r=>`<p>${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)} <span class="muted tiny">${r.mine?'Your review':''}</span><br>${esc(r.comment)}</p>`).join('')}${p.you_reviewed?'':`<form id="review-form"><div class="field"><label>Rating</label><select name="rating"><option value="5">5 — Excellent</option><option value="4">4 — Good</option><option value="3">3 — Okay</option><option value="2">2 — Poor</option><option value="1">1 — Bad</option></select></div><div class="field"><label>Review</label><textarea name="comment"></textarea></div><button class="btn secondary">Submit review</button></form>`}</section>`:''}</aside></div>`;v.onclick=async e=>{const b=e.target.closest('[data-status]');if(b)await act(b,async()=>{await api(`/partnerships/${id}/status`,{method:'POST',body:{status:b.dataset.status}});toast('Collaboration stage updated');await route()})};v.onchange=async e=>{const b=e.target.closest('[data-milestone]');if(b)await act(b,async()=>{await api(`/partnerships/${id}/milestones/${b.dataset.milestone}/toggle`,{method:'POST'});await route()})};$('#add-milestone').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));await act(e.submitter,async()=>{await api(`/partnerships/${id}/milestones`,{method:'POST',body:d});await route()})};$('#add-metric').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));d.sdg=+d.sdg;d.value=+d.value;await act(e.submitter,async()=>{await api(`/partnerships/${id}/metrics`,{method:'POST',body:d});toast('Outcome added');await route()})};$('#send-message').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;const body=f.body.value;await act(e.submitter,async()=>{await api(`/partnerships/${id}/messages`,{method:'POST',body:{body}});f.reset();await route()})};$('#review-form')?.addEventListener('submit',async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));d.rating=+d.rating;await act(e.submitter,async()=>{await api(`/partnerships/${id}/review`,{method:'POST',body:d});await route()})})}
async function impactPage(v){const [i,ov]=await Promise.all([api('/analytics/impact'),api('/analytics/overview')]);const sd=Object.entries(i.sdgs||{});const cov=Object.entries(ov.sdg_coverage||{}).sort((a,b)=>+a[0]-+b[0]);v.innerHTML=pageHead('DELIVERY / EVIDENCE & OUTCOMES','Measure what changed.','A clear view of collaboration delivery and the SDGs your organisation contributes to.',`<button class="btn secondary" id="export-csv">↓ Export CSV</button><button class="btn secondary" onclick="window.print()">Print report</button><button class="btn primary" id="generate-report">✳ Draft impact narrative</button>`)+`<div class="layout-grid cols-4">${stat('Collaborations',i.partnerships,'All statuses','⇄')}${stat('Completed',i.completed,'Partnerships closed','✓')}${stat('Milestone delivery',`${i.milestones_total?Math.round(i.milestones_done/i.milestones_total*100):0}%`,`${i.milestones_done} of ${i.milestones_total} milestones`,'◴')}${stat('SDGs with outcomes',sd.length,'Metrics recorded in partnerships','◌')}</div><div class="split section-gap"><section class="card">${cardHead('Recorded outcomes','<span class="pill blue">PARTNERSHIP LEDGER</span>')}${sd.length?sd.map(([n,d])=>`<div style="padding:15px 0;border-bottom:1px solid var(--line)"><div class="row">${sdgChips([+n])}<strong>${esc(d.title)}</strong><span class="pill">${d.metrics.length} metrics</span></div>${d.metrics.map(m=>`<div class="metric-row"><div style="flex:1"><strong class="small-text">${esc(m.name)}</strong><div class="muted tiny">${esc(m.partnership)} · ${esc(m.verification_status||'self_reported')}</div>${m.evidence_url?`<a class="muted tiny" href="${safeUrl(m.evidence_url)}" target="_blank" rel="noopener noreferrer">View evidence ↗</a>`:''}</div><div class="metric-number">${num(m.value)} <span class="muted tiny">${esc(m.unit)}</span></div></div>`).join('')}</div>`).join(''):empty('Your impact ledger is empty','Add metrics in a collaboration workspace to start building an outcome record.','<a class="btn primary" href="#/partnerships">Open collaborations</a>')}<div id="impact-report"></div></section><section class="card">${cardHead('Ecosystem SDG coverage','<span class="pill">NETWORK VIEW</span>')}<p class="muted small-text">How frequently each SDG appears in organisation profiles across the network. This is coverage, not proof of impact.</p><div class="sdg-coverage">${cov.map(([n,c])=>`<div class="coverage-row"><span class="sdg-chip" style="background:${SDG[n]?.[1]||'#777'}">${n}</span><span>${esc(SDG[n]?.[0]||'SDG')}</span><div class="coverage-track"><i style="width:${100*c/Math.max(1,...cov.map(x=>x[1]))}%;background:${SDG[n]?.[1]||'#777'}"></i></div><b>${c}</b></div>`).join('')}</div></section></div><div class="notice section-gap">Evidence standard: distinguish activities, outputs and outcomes. PACT supports evidence links and administrator review, but does not independently authenticate sources or guarantee the truth of an impact claim.</div>`;$('#export-csv').onclick=async e=>act(e.target,async()=>{const r=await api('/export/partnerships.csv',{raw:true});const url=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=url;a.download='pact-partnerships.csv';a.click();URL.revokeObjectURL(url)});$('#generate-report').onclick=async e=>act(e.target,async()=>{const r=await api('/ai/report',{method:'POST'});$('#impact-report').innerHTML=`<div class="divider"></div><h2>Draft impact narrative</h2><p class="muted tiny">${r.ai?'AI assisted':'Generated using built-in fallback'} · Review before publication</p><div style="white-space:pre-wrap;line-height:1.8">${esc(r.text)}</div>`})}
async function directoryPage(v){v.innerHTML=pageHead('ECOSYSTEM / DIRECTORY','Meet the organisations behind the work.','Search the cross-sector network by organisation, expertise and location.')+`<div class="filterbar"><input id="org-q" placeholder="Organisation, sector, capability…"><select id="org-type"><option value="">All organisation types</option>${TYPES.map(t=>`<option>${t}</option>`).join('')}</select><label style="display:flex;align-items:center;gap:6px;font-size:11px"><input type="checkbox" id="org-verified" style="width:auto"> Verified only</label></div><div id="org-results" class="layout-grid cols-3"></div>`;const load=async()=>{const params=new URLSearchParams({q:$('#org-q').value,type:$('#org-type').value,verified:$('#org-verified').checked?'true':'false'});const rows=await api('/orgs?'+params);$('#org-results').innerHTML=rows.length?rows.map((o,i)=>`<a class="card" href="#/org/${o.id}"><div class="row">${orgAvatar(o,i)}<div style="flex:1"><h3 style="margin:0">${esc(o.name)}</h3><div class="muted tiny">${esc(o.type)} · ${esc(o.sector||'General')}</div></div>${o.verified?'<span class="pill green">✓</span>':''}</div><p class="muted small-text" style="margin:15px 0">${esc((o.description||'No organisation summary yet.').slice(0,155))}${(o.description||'').length>155?'…':''}</p><div class="tag-row">${sdgChips(o.sdgs)}</div><div class="divider"></div><div class="row" style="justify-content:space-between"><span class="muted tiny">${esc([o.city,o.country].filter(Boolean).join(', ')||'Location not provided')}</span><span class="pill blue">Trust ${o.trust??'—'}/100</span></div></a>`).join(''):empty('No organisations found','Try another search term or broaden your filters.')};let timer;$('#org-q').oninput=()=>{clearTimeout(timer);timer=setTimeout(()=>load().catch(e=>toast(e.message,true)),250)};$('#org-type').onchange=load;$('#org-verified').onchange=load;await load()}
async function orgPage(v,id){const o=await api('/orgs/'+id),mine=o.id===S.user.org?.id;v.innerHTML=pageHead('ECOSYSTEM / ORGANISATION PROFILE',o.name,`${o.type} · ${o.sector||'Cross-sector'} · ${[o.city,o.country].filter(Boolean).join(', ')}`,mine?`<a class="btn primary" href="#/profile">Edit organisation →</a>`:`<button class="btn primary" data-start="${o.id}">Propose collaboration →</button>`)+`<div class="layout-grid cols-4">${stat('Trust score',`${o.trust??0}/100`,o.verified?'Verification active':'Not verified','◇')}${stat('Open needs',o.listings.filter(l=>l.kind==='need'&&l.status==='open').length,'Resources requested','!')}${stat('Open offers',o.listings.filter(l=>l.kind==='offer'&&l.status==='open').length,'Resources available','＋')}${stat('SDGs tagged',(o.sdgs||[]).length,'Focus areas','◌')}</div><div class="split section-gap"><section class="card">${cardHead('Organisation brief')}<p>${esc(o.description||'This organisation has not added a description yet.')}</p><div class="tag-row">${sdgChips(o.sdgs)}</div>${o.website?`<p class="section-gap"><a href="${safeUrl(o.website)}" target="_blank" rel="noopener noreferrer" class="btn secondary">Visit website ↗</a></p>`:''}<div class="divider"></div>${cardHead('Needs & offers')}<div class="layout-grid cols-2">${['need','offer'].map(k=>`<div><div class="kicker">${k==='need'?'Needs support with':'Can contribute'}</div>${o.listings.filter(l=>l.kind===k&&l.status==='open').map(l=>`<div class="list-row"><span class="stat-icon">${k==='need'?'!':'＋'}</span><div class="grow"><strong>${esc(l.title)}</strong><p>${esc(l.description)}</p><div class="tag-row">${sdgChips(l.sdgs)}</div></div></div>`).join('')||'<p class="muted tiny">No open listings.</p>'}</div>`).join('')}</div></section><section class="card">${cardHead('Trust & community feedback')}<p class="muted small-text">Trust score is a platform signal based on available profile, verification, rating and collaboration information—not a guarantee.</p><div class="stat-value">${o.trust??0}<span class="muted" style="font-size:13px"> / 100</span></div><div class="progress-track"><i style="width:${o.trust??0}%"></i></div><div class="divider"></div>${o.reviews?.length?o.reviews.map(r=>`<div class="metric-row"><div style="flex:1"><strong class="small-text">${esc(r.from)}</strong><p class="muted tiny" style="margin:4px 0">${esc(r.comment||'No written comment.')}</p></div><span class="pill orange">${r.rating}/5 ★</span></div>`).join(''):empty('No reviews yet','Reviews are available after completed collaborations.')}</section></div>`}
async function profilePage(v){const o=await api('/orgs/'+S.user.org.id),list=await api('/listings?mine=true');const selected=new Set((o.sdgs||[]).filter(n=>n!==17));v.innerHTML=pageHead('SETTINGS / YOUR ORGANISATION','Make your organisation legible to partners.','A specific profile and well-written opportunities lead to better recommendations.')+`<div class="layout-grid cols-2"><section class="card">${cardHead('Organisation identity')}<form id="org-form"><div class="field"><label>Organisation name</label><input name="name" required value="${esc(o.name)}"></div><div class="form-grid"><div class="field"><label>Type</label><select name="type">${TYPES.map(t=>`<option ${o.type===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label>Sector</label><input name="sector" value="${esc(o.sector||'')}"></div></div><div class="field"><label>About the organisation</label><textarea name="description" placeholder="Mission, capabilities, communities served…">${esc(o.description||'')}</textarea></div><div class="field"><label>Website</label><input name="website" type="url" value="${esc(o.website||'')}" placeholder="https://"></div><div class="form-grid"><div class="field"><label>City</label><input name="city" value="${esc(o.city||'')}"></div><div class="field"><label>Country</label><input name="country" value="${esc(o.country||'India')}"></div></div><div class="field"><label>SDG focus areas</label><div class="tag-row">${Object.entries(SDG).filter(([n])=>n!=='17').map(([n,d])=>`<label class="pill" style="cursor:pointer"><input type="checkbox" data-sdg-pick="${n}" ${selected.has(+n)?'checked':''} style="width:auto;margin:0"> <span style="background:${d[1]};color:white;padding:2px 5px;border-radius:4px">${n}</span> ${esc(d[0])}</label>`).join('')}</div><p class="muted tiny">SDG 17 is always included because this platform is built around partnerships.</p></div><button class="btn primary">Save organisation profile</button></form></section><section class="layout-grid"><div class="card">${cardHead('Publish a need or offer','<span class="pill green">MARKETPLACE</span>')}<p class="muted small-text">Be concrete: describe what you need or can contribute, who it helps, and the time or scale involved.</p><form id="listing-form"><div class="form-grid"><div class="field"><label>Listing type</label><select name="kind"><option value="need">We need support</option><option value="offer">We can contribute</option></select></div><div class="field"><label>Remote-friendly?</label><select name="remote"><option value="true">Yes</option><option value="false">No / local only</option></select></div></div><div class="field"><label>Title</label><input name="title" required minlength="3" placeholder="e.g. Need volunteer data analysts"></div><div class="field"><label>Description</label><textarea name="description" required placeholder="Explain the need/offer, target group, scope and constraints…"></textarea></div><div class="field"><label>Tags (comma-separated)</label><input name="tags" placeholder="data, volunteers, education"></div><button class="btn primary">Publish opportunity →</button></form></div><div class="card">${cardHead('Your published opportunities',`<span class="pill">${list.length} LISTINGS</span>`)}<div class="list-stack">${list.map((l,i)=>`<div class="list-row">${orgAvatar({name:l.title},i)}<div class="grow"><strong>${esc(l.title)}</strong><p>${pill(l.kind)} ${esc(l.status)} · ${sdgChips(l.sdgs)}</p></div><button class="btn small secondary" data-toggle-listing="${l.id}">${l.status==='open'?'Close':'Reopen'}</button><button class="btn small danger" data-delete-listing="${l.id}" aria-label="Delete listing">×</button></div>`).join('')||empty('No listings published','Create your first need or offer above.')}</div></div></section></div>`;$('#org-form').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));d.lat=o.lat??null;d.lon=o.lon??null;d.sdgs=[...document.querySelectorAll('[data-sdg-pick]:checked')].map(x=>+x.dataset.sdgPick);await act(e.submitter,async()=>{await api('/orgs/me',{method:'PUT',body:d});S.user=await api('/auth/me');toast('Organisation profile saved');await route()})};$('#listing-form').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));d.tags=d.tags.split(',').map(x=>x.trim()).filter(Boolean);d.remote_ok=d.remote==='true';delete d.remote;await act(e.submitter,async()=>{await api('/listings',{method:'POST',body:d});toast('Opportunity published');await route()})};v.onclick=async e=>{const t=e.target.closest('[data-toggle-listing]'),d=e.target.closest('[data-delete-listing]');if(t)await act(t,async()=>{await api(`/listings/${t.dataset.toggleListing}/toggle`,{method:'POST'});await route()});if(d&&confirm('Delete this opportunity? This cannot be undone.'))await act(d,async()=>{await api(`/listings/${d.dataset.deleteListing}`,{method:'DELETE'});await route()})}}
async function copilotPage(v){const draw=()=>$('#copilot-messages').innerHTML=S.chat.map(m=>`<div class="copilot-bubble ${m.role==='user'?'user':''}">${esc(m.content)}</div>`).join('')||`<div class="copilot-bubble"><b>Hi ${esc(S.user.full_name.split(' ')[0])}.</b><br>I can help you decide which partner to approach, turn a broad goal into milestones, or identify gaps in your collaboration portfolio. I use your platform context when available.</div>`;v.innerHTML=pageHead('INTELLIGENCE / COPILOT','Think through the next move.','A context-aware assistant for partnership planning. AI suggestions are drafts—not commitments or verified facts.')+`<div class="copilot-layout"><section class="card copilot-chat"><div class="row" style="justify-content:space-between"><div><h2>PACT copilot</h2><p class="muted tiny">Connected to your organisation context</p></div><span class="pill green">● READY</span></div><div class="divider"></div><div class="copilot-messages" id="copilot-messages"></div><form id="copilot-form" class="copilot-input"><textarea name="message" placeholder="Ask a question about your partnerships…" required></textarea><button class="btn primary">Send ↗</button></form></section><aside class="card copilot-aside">${cardHead('Starter prompts')}<button class="suggestion" data-prompt="Which partner should we contact first, and why?">Which partner should we contact first?</button><button class="suggestion" data-prompt="What are the biggest gaps in our current organisation profile?">Find gaps in our profile</button><button class="suggestion" data-prompt="Suggest three realistic partnership milestones for an SDG 17 pilot.">Draft a partnership plan</button><button class="suggestion" data-prompt="How can we measure outcomes rather than just activities?">Improve our impact measures</button><div class="notice section-gap">Do not submit confidential personal data or treat AI output as independently verified advice.</div></aside></div>`;const send=async text=>{S.chat.push({role:'user',content:text});draw();const f=$('#copilot-form');f.querySelector('button').disabled=true;try{const r=await api('/ai/copilot',{method:'POST',body:{message:text,history:S.chat.slice(0,-1).slice(-8)}});S.chat.push({role:'assistant',content:r.text})}catch(e){S.chat.push({role:'assistant',content:e.message})}finally{f.querySelector('button').disabled=false;draw();$('#copilot-messages').scrollTop=1e6}};$('#copilot-form').onsubmit=e=>{e.preventDefault();const f=e.currentTarget,t=f.message.value.trim();if(!t)return;f.reset();send(t)};v.onclick=e=>{const b=e.target.closest('[data-prompt]');if(b)send(b.dataset.prompt)};draw()}
async function settingsPage(v){const st=await api('/ai/status'),admin=S.user.role==='admin';let cfg=admin?await api('/ai/settings'):st;v.innerHTML=pageHead('SETTINGS / INTELLIGENCE','Choose how PACT thinks.','Use the built-in matching engine or connect an OpenAI-compatible local or hosted model.')+`<div class="layout-grid cols-2"><section class="card">${cardHead('AI connection status',`<span class="pill ${st.up?'green':'orange'}">${st.up?'● ONLINE':'● OFFLINE'}</span>`)}<div class="metric-row"><span class="stat-icon">✳</span><div style="flex:1"><strong class="small-text">Chat model</strong><div class="muted tiny">${esc(st.model||'No model selected')}</div></div></div><div class="metric-row"><span class="stat-icon">⌕</span><div style="flex:1"><strong class="small-text">Embedding model</strong><div class="muted tiny">${esc(st.embed_model||'Built-in semantic vectors')}</div></div></div><p class="muted small-text section-gap">When a model is offline, core matching and selected AI features use built-in fallbacks. Check the label on generated content before relying on it.</p><div class="notice">Local model example: start Ollama, pull a compatible chat model and embedding model, then enter your local OpenAI-compatible endpoint below.</div></section><section class="card">${cardHead('Configure model',admin?'<span class="pill blue">ADMIN</span>':'<span class="pill">READ ONLY</span>')}${admin?`<form id="ai-settings"><div class="field"><label>OpenAI-compatible base URL</label><input name="base_url" value="${esc(cfg.base_url||'http://localhost:11434/v1')}" placeholder="http://localhost:11434/v1"></div><div class="field"><label>API key (optional for local servers)</label><input name="api_key" type="password" placeholder="${cfg.api_key?'Saved — leave blank to keep current key':'Enter API key if required'}" autocomplete="new-password"></div><div class="field"><label>Chat model identifier</label><input name="model" value="${esc(cfg.model||'')}" placeholder="e.g. llama3.2"></div><div class="field"><label>Embedding model identifier</label><input name="embed_model" value="${esc(cfg.embed_model||'')}" placeholder="e.g. nomic-embed-text"></div><div class="row"><button class="btn primary">Save configuration</button><button type="button" class="btn secondary" id="detect-models">Detect models</button><button type="button" class="btn secondary" id="test-model">Test</button></div><p id="model-result" class="muted tiny section-gap"></p></form>`:`<p class="muted small-text">Only administrators can change the shared AI connection. You can still use the built-in matching engine.</p>`}</section></div><section class="card section-gap">${cardHead('Matching transparency')}<p class="muted small-text">PACT combines semantic similarity, SDG alignment, geographic suitability, trust signals and reciprocity. The score helps prioritise introductions; it is not a prediction that a partnership will succeed.</p><div class="layout-grid cols-3"><div class="list-row"><span class="stat-icon">◎</span><div><strong class="small-text">Meaning</strong><p>Needs and offers describe compatible capabilities.</p></div></div><div class="list-row"><span class="stat-icon">◌</span><div><strong class="small-text">Shared SDGs</strong><p>Relevant development goals overlap.</p></div></div><div class="list-row"><span class="stat-icon">◇</span><div><strong class="small-text">Trust signals</strong><p>Profile completeness and collaboration history.</p></div></div></div></section>`;if(!admin)return;const f=$('#ai-settings');f.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f));if(!d.api_key)d.api_key='';await act(e.submitter,async()=>{await api('/ai/settings',{method:'POST',body:d});$('#model-result').textContent='Configuration saved. Test the connection before using AI-assisted features.';toast('AI configuration saved')})};$('#detect-models').onclick=async e=>act(e.target,async()=>{const url=f.base_url.value,key=f.api_key.value;const r=await api('/ai/models?base='+encodeURIComponent(url)+'&key='+encodeURIComponent(key));$('#model-result').textContent=r.ok?`Models found: ${r.models.join(', ')||'none returned'}`:r.error});$('#test-model').onclick=async e=>act(e.target,async()=>{const r=await api('/ai/test',{method:'POST'});$('#model-result').textContent=r.ok?'Connection successful: '+r.reply:'Connection failed: '+r.error})}
async function networkPage(v){const g=await api('/analytics/network');const nodes=g.nodes||[],edges=g.edges||[];const W=900,H=500;const placed=nodes.map((n,i)=>({...n,x:W/2+Math.cos(i*2*Math.PI/Math.max(nodes.length,1))*Math.min(300,80+nodes.length*14),y:H/2+Math.sin(i*2*Math.PI/Math.max(nodes.length,1))*Math.min(175,60+nodes.length*8)}));const byId=Object.fromEntries(placed.map(n=>[n.id,n]));v.innerHTML=pageHead('ECOSYSTEM / RELATIONSHIPS','See the collaboration network.','Explore the ecosystem graph. Connections show active, completed or negotiating partnerships.',`<a class="btn secondary" href="#/orgs">Browse organisations →</a>`)+`<section class="card"><div class="row" style="justify-content:space-between"><div><h2>Network topology</h2><p class="muted tiny">${nodes.length} organisations · ${edges.length} live or completed relationships</p></div><div class="tag-row"><span class="pill green">● Active / completed</span><span class="pill blue">● Negotiating</span></div></div><div style="overflow:auto"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Organisation partnership network" style="width:100%;min-width:650px;height:auto;background:radial-gradient(circle at center,#f7f9fc,#fff);border-radius:14px">${edges.map(e=>{const a=byId[e.a],b=byId[e.b];return a&&b?`<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="${e.status==='negotiating'?'#3e6ff4':'#149b87'}" stroke-width="${e.status==='completed'?3:2}" opacity=".5" ${e.status==='negotiating'?'stroke-dasharray="5 5"':''}><title>${esc(e.title)} · ${esc(e.status)}</title></line>`:''}).join('')}${placed.map((n,i)=>`<a href="#/org/${n.id}"><circle cx="${n.x}" cy="${n.y}" r="${Math.max(13,Math.min(23,12+(n.trust||30)/10))}" fill="${['#3e6ff4','#149b87','#e69a36','#7b61d1','#d85d62'][i%5]}" stroke="${n.verified?'#c9f36b':'white'}" stroke-width="${n.verified?5:3}"/><text x="${n.x}" y="${n.y+36}" text-anchor="middle" font-size="11" fill="#142033">${esc(n.name.length>24?n.name.slice(0,22)+'…':n.name)}</text></a>`).join('')}</svg></div><div class="divider"></div><div class="layout-grid cols-3">${nodes.slice(0,6).map((n,i)=>`<a class="list-row" href="#/org/${n.id}">${orgAvatar(n,i)}<div class="grow"><strong>${esc(n.name)}</strong><p>${esc(n.type)} · trust ${n.trust??'—'}</p></div><span>→</span></a>`).join('')}</div></section>`}
async function adminPage(v){if(S.user.role!=='admin'){v.innerHTML=empty('Restricted area','This workspace is available to administrators only.');return}const d=await api('/admin/overview');v.innerHTML=pageHead('GOVERNANCE / TRUST & SAFETY','Keep the ecosystem accountable.','Review organisation verification, manage account access and inspect administrative activity.')+`<div class="layout-grid cols-3">${stat('Registered accounts',d.users.length,'Across all organisation types','♙')}${stat('Pending verification',d.pending.length,'Organisation reviews waiting','◇')}${stat('Recent audit events',d.audit.length,'Most recent recorded actions','▤')}</div><div class="layout-grid cols-2 section-gap"><section class="card">${cardHead('Verification queue','<span class="pill orange">${d.pending.length} PENDING</span>')}<div class="list-stack">${d.pending.map((o,i)=>`<div class="list-row">${orgAvatar(o,i)}<div class="grow"><strong>${esc(o.name)}</strong><p>${esc(o.type)} · ${esc(o.city||'')} · ${esc(o.sector||'')}</p></div><button class="btn primary small" data-verify="${o.id}">Verify</button></div>`).join('')||empty('Queue clear','No organisations are waiting for verification.')}</div></section><section class="card">${cardHead('Account access')}<div class="table-wrap"><table><thead><tr><th>Member</th><th>Role</th><th>Status</th><th>Action</th></tr></thead><tbody>${d.users.map(u=>`<tr><td><b>${esc(u.name)}</b><br><span class="muted">${esc(u.email)}</span></td><td>${esc(u.role)}</td><td>${pill(u.active?'active':'disabled')}</td><td>${u.role==='admin'?'—':`<button class="btn small secondary" data-user-toggle="${u.id}">${u.active?'Disable':'Enable'}</button>`}</td></tr>`).join('')}</tbody></table></div></section></div><section class="card section-gap">${cardHead('Impact evidence review',`<span class="pill orange">${(d.impact_review||[]).length} PENDING</span>`)}<p class="muted small-text">Only mark a claim verified after checking the linked evidence and recording a concise review note.</p><div class="list-stack">${(d.impact_review||[]).map(m=>`<div class="list-row"><span class="stat-icon">◌</span><div class="grow"><strong>${esc(m.name)} · ${num(m.value)} ${esc(m.unit)}</strong><p>${esc(m.partnership)} · ${esc(m.org_a)} / ${esc(m.org_b)} · SDG ${m.sdg}</p>${m.evidence_url?`<a class="muted tiny" target="_blank" rel="noopener noreferrer" href="${safeUrl(m.evidence_url)}">Open evidence ↗</a>`:'<span class="pill red">No evidence URL</span>'}</div><button class="btn small primary" data-impact-review="${m.id}" data-review-status="verified" ${m.evidence_url?'':'disabled'}>Verify</button><button class="btn small danger" data-impact-review="${m.id}" data-review-status="rejected">Reject</button></div>`).join('')||empty('No impact claims waiting','Metrics with evidence links appear here when submitted for review.')}</div></section><section class="card section-gap">${cardHead('Audit trail','<span class="pill">LATEST EVENTS</span>')}<div class="table-wrap"><table><thead><tr><th>Action</th><th>Details</th><th>User ID</th><th>Timestamp</th></tr></thead><tbody>${d.audit.map(a=>`<tr><td><b>${esc(a.action)}</b></td><td>${esc(a.detail||'—')}</td><td>${a.user_id??'—'}</td><td>${esc(a.at||'')}</td></tr>`).join('')}</tbody></table></div></section>`;v.onclick=async e=>{const ver=e.target.closest('[data-verify]'),u=e.target.closest('[data-user-toggle]'),ir=e.target.closest('[data-impact-review]');if(ver)await act(ver,async()=>{await api(`/orgs/${ver.dataset.verify}/verify`,{method:'POST'});toast('Organisation verified');await route()});if(u)await act(u,async()=>{await api(`/admin/users/${u.dataset.userToggle}/toggle`,{method:'POST'});await route()});if(ir)await act(ir,async()=>{const note=prompt('Review note (required for audit context):','');if(note===null)return;await api(`/admin/impact/${ir.dataset.impactReview}/review`,{method:'POST',body:{status:ir.dataset.reviewStatus,note}});toast('Impact claim review saved');await route()})}}
async function boot(){if(!S.token){authView();return}try{S.user=await api('/auth/me')}catch{S.token=null;localStorage.removeItem('pact_token');localStorage.removeItem('ph_token');authView();return}const ns=await api('/notifications').catch(()=>[]);S.unread=ns.filter(n=>!n.read).length;shell();route();connectWs()}
function connectWs(){S.ws?.close();try{const ws=S.ws=new WebSocket(`${location.protocol==='https:'?'wss':'ws'}://${location.host}/ws?token=${encodeURIComponent(S.token)}`);const ping=setInterval(()=>ws.readyState===1&&ws.send('ping'),25000);ws.onmessage=e=>{try{const d=JSON.parse(e.data);if(d.type==='notification'){S.unread++;$('#notif-dot')?.classList.remove('hidden');toast(d.text)}if(d.type==='message'&&d.message.partnership_id===S.curPart&&location.hash.startsWith('#/partnership/'))route()}catch{}};ws.onclose=()=>{clearInterval(ping);if(S.token)setTimeout(()=>S.token&&connectWs(),5000)}}catch{}}
boot();
})();
